package com.littlemakers.village.nativeapp;
import java.util.*;
public final class SchoolContentTest {
 static int checks;static void check(boolean v,String m){checks++;if(!v)throw new AssertionError(m);}
 public static void main(String[]args){Set<Integer>keys=new HashSet<>();Set<String>rewards=new HashSet<>();int total=0;for(int grade=0;grade<=10;grade++)for(int subject=0;subject<3;subject++)for(int index=0;index<SchoolContent.count(subject);index++){SchoolContent.Question q=SchoolContent.at(grade,subject,index);check(keys.add(q.key),"key collision");check(rewards.add(q.rewardKey()),"reward collision");check(q.prompt.trim().length()>=3&&q.explanation.length()>10,"empty teaching copy "+q.key);check(q.choices.length==3&&new HashSet<>(Arrays.asList(q.choices)).size()==3,"choice uniqueness");for(int i=0;i<3;i++)check(q.correct(i)==q.choices[i].equals(q.answer),"correct answer mapping");check(!q.correct(-1)&&!q.correct(3),"bounds");total++;}check(total==264,"exact content inventory");check(SchoolContent.at(0,0,0).answer.equals("3"),"nursery count");check(SchoolContent.at(0,0,9).answer.equals("3"),"nursery pair");check(SchoolContent.at(3,0,3).answer.equals("16"),"rectangle perimeter");check(SchoolContent.at(4,0,3).answer.equals("3"),"factor lesson");check(SchoolContent.at(5,0,1).answer.equals("0.6"),"decimal exactness");check(SchoolContent.at(6,0,2).answer.equals("4:3"),"ratio");check(SchoolContent.at(7,0,2).answer.equals("80"),"triangle");check(SchoolContent.at(8,0,2).answer.equals("100"),"interest");check(SchoolContent.at(9,0,1).answer.equals("5"),"distance");check(SchoolContent.at(10,0,0).answer.equals("2 and 3"),"quadratic roots");check(SchoolContent.at(10,0,7).answer.equals("5/13"),"trigonometry");for(int n=0;n<210;n++){int a=CompanionCast.first(n),b=CompanionCast.second(n);check(a>=0&&a<8&&b>=0&&b<8&&a!=b,"distinct story pair");}check(CompanionCast.NAMES.length==8&&CompanionCast.COLORS.length==8,"cast inventory");for(int[]bad:new int[][]{{-1,0,0},{11,0,0},{0,3,0},{0,0,12},{0,1,6}}){try{SchoolContent.at(bad[0],bad[1],bad[2]);throw new AssertionError("invalid activity accepted");}catch(IllegalArgumentException expected){checks++;}}System.out.println("PASS "+checks+" checks: 264 bounded activities, unique reward keys and choices, numeric reference cases, eight companions and all 210 distinct story pairs. Content is a starter trail, not a full curriculum.");}
}
